function review({project,sceneId,inputs}){
  const scene=project.scenes.find(entry=>entry.id===sceneId);
  const nodes=project.nodes.filter(node=>node.sceneId===sceneId);
  const issues=[];
  for(const node of nodes){
    const missing=[];
    if(!node.date)missing.push('日期');
    if(!node.locationId)missing.push('地点');
    const hasText=[node.summary,node.text,node.condition?.description,...node.lines.map(line=>line.text)]
      .some(value=>typeof value==='string'&&value.trim());
    if(!hasText)missing.push('正文');
    if(missing.length)issues.push({node,missing});
  }
  const lines=[scene.name+' · 共 '+nodes.length+' 个节点，'+issues.length+' 个待检查'];
  for(const {node,missing} of issues.slice(0,100))lines.push('• '+node.title.slice(0,100)+' · '+missing.join('、'));
  if(issues.length>100)lines.push('另有 '+(issues.length-100)+' 个节点');
  if(!issues.length)lines.push('当前场景的节点已填写日期、地点和正文。');
  if(inputs?.includeNodeCount)lines.push('场景 ID '+sceneId);
  return {message:lines.join('\n'),links:issues.slice(0,100).map(({node})=>({nodeId:node.id,label:node.title.slice(0,160)||node.id}))};
}
StoryTree.register({
  review,
  outline(context){
    const result=review(context);
    const title=context.inputs.title.trim();
    if(!title)throw Error('请输入大纲标题。');
    return {...result,commands:[{type:'outline.create',args:{title,text:result.message}}]};
  }
});
